 "INSERT INTO pve_engagements\n         (player_id, monster_id, spawn_round, next_hit_at_ms, expires_at_ms, hit_sequence, updated_at_ms, last_skill_at_ms,attackers489)\n       SELECT ?, ?, ?, ?, ?, 0, ?, ?, ? FROM players current_player\n       WHERE current_player.id = ? AND current_player.hp > 0\n         AND current_player.area = ? AND current_player.channel = ? AND current_player.arena_match_id = ?\n         AND current_player.realtime_scope_version = ?\n         AND EXISTS (SELECT 1 FROM monsters current_monster\n           WHERE current_monster.id = ? AND current_monster.spawn_round = ? AND current_monster.hp > 0)\n       ON CONFLICT(player_id) DO UPDATE SET\n         attackers489 = CASE WHEN json_extract(CASE WHEN pve_engagements.attackers489='{}' THEN json_object(pve_engagements.monster_id,json_object('monster_id',pve_engagements.monster_id,'spawn_round',pve_engagements.spawn_round,'next_hit_at_ms',pve_engagements.next_hit_at_ms,'last_skill_at_ms',pve_engagements.last_skill_at_ms)) ELSE pve_engagements.attackers489 END,'$.'||json_quote(excluded.monster_id)||'.spawn_round')=excluded.spawn_round THEN CASE WHEN pve_engagements.attackers489='{}' THEN json_object(pve_engagements.monster_id,json_object('monster_id',pve_engagements.monster_id,'spawn_round',pve_engagements.spawn_round,'next_hit_at_ms',pve_engagements.next_hit_at_ms,'last_skill_at_ms',pve_engagements.last_skill_at_ms)) ELSE pve_engagements.attackers489 END\n WHEN (SELECT count(*) FROM json_each(CASE WHEN pve_engagements.attackers489='{}' THEN json_object(pve_engagements.monster_id,json_object('monster_id',pve_engagements.monster_id,'spawn_round',pve_engagements.spawn_round,'next_hit_at_ms',pve_engagements.next_hit_at_ms,'last_skill_at_ms',pve_engagements.last_skill_at_ms)) ELSE pve_engagements.attackers489 END))<32 OR json_type(CASE WHEN pve_engagements.attackers489='{}' THEN json_object(pve_engagements.monster_id,json_object('monster_id',pve_engagements.monster_id,'spawn_round',pve_engagements.spawn_round,'next_hit_at_ms',pve_engagements.next_hit_at_ms,'last_skill_at_ms',pve_engagements.last_skill_at_ms)) ELSE pve_engagements.attackers489 END,'$.'||json_quote(excluded.monster_id)) IS NOT NULL\n THEN json_set(CASE WHEN pve_engagements.attackers489='{}' THEN json_object(pve_engagements.monster_id,json_object('monster_id',pve_engagements.monster_id,'spawn_round',pve_engagements.spawn_round,'next_hit_at_ms',pve_engagements.next_hit_at_ms,'last_skill_at_ms',pve_engagements.last_skill_at_ms)) ELSE pve_engagements.attackers489 END,'$.'||json_quote(excluded.monster_id),json_object('monster_id',excluded.monster_id,'spawn_round',excluded.spawn_round,'next_hit_at_ms',excluded.next_hit_at_ms,'last_skill_at_ms',excluded.last_skill_at_ms)) ELSE CASE WHEN pve_engagements.attackers489='{}' THEN json_object(pve_engagements.monster_id,json_object('monster_id',pve_engagements.monster_id,'spawn_round',pve_engagements.spawn_round,'next_hit_at_ms',pve_engagements.next_hit_at_ms,'last_skill_at_ms',pve_engagements.last_skill_at_ms)) ELSE pve_engagements.attackers489 END END,\n         monster_id = CASE WHEN pve_engagements.expires_at_ms >= excluded.updated_at_ms\n    AND EXISTS (SELECT 1 FROM monsters live_monster\n      WHERE live_monster.id = pve_engagements.monster_id\n        AND live_monster.spawn_round = pve_engagements.spawn_round AND live_monster.hp > 0) THEN pve_engagements.monster_id ELSE excluded.monster_id END,\n         spawn_round = CASE WHEN pve_engagements.expires_at_ms >= excluded.updated_at_ms\n    AND EXISTS (SELECT 1 FROM monsters live_monster\n      WHERE live_monster.id = pve_engagements.monster_id\n        AND live_monster.spawn_round = pve_engagements.spawn_round AND live_monster.hp > 0) THEN pve_engagements.spawn_round ELSE excluded.spawn_round END,\n         next_hit_at_ms = CASE WHEN pve_engagements.expires_at_ms >= excluded.updated_at_ms\n    AND EXISTS (SELECT 1 FROM monsters live_monster\n      WHERE live_monster.id = pve_engagements.monster_id\n        AND live_monster.spawn_round = pve_engagements.spawn_round AND live_monster.hp > 0)\n           THEN MIN(pve_engagements.next_hit_at_ms, excluded.next_hit_at_ms) ELSE excluded.next_hit_at_ms END,\n         expires_at_ms = CASE WHEN pve_engagements.expires_at_ms >= excluded.updated_at_ms\n    AND EXISTS (SELECT 1 FROM monsters live_monster\n      WHERE live_monster.id = pve_engagements.monster_id\n        AND live_monster.spawn_round = pve_engagements.spawn_round AND live_monster.hp > 0)\n           THEN MAX(pve_engagements.expires_at_ms, excluded.expires_at_ms) ELSE excluded.expires_at_ms END,\n         last_skill_at_ms = CASE WHEN pve_engagements.expires_at_ms >= excluded.updated_at_ms\n    AND EXISTS (SELECT 1 FROM monsters live_monster\n      WHERE live_monster.id = pve_engagements.monster_id\n        AND live_monster.spawn_round = pve_engagements.spawn_round AND live_monster.hp > 0) THEN pve_engagements.last_skill_at_ms ELSE excluded.last_skill_at_ms END,\n         updated_at_ms = excluded.updated_at_ms\n       RETURNING player_id",
