 "UPDATE main.players SET \"combat_lock_until_ms\"=? WHERE \"id\"=? AND \"account_id\" IS ? AND \"area\" IS ? AND \"channel\" IS ? AND \"arena_match_id\" IS ? AND \"realtime_scope_version\" IS ? AND \"max_hp\" IS ? AND \"x\" IS ? AND \"y\" IS ? AND \"movement_checked_at_ms\" IS ? AND \"movement_debt_ms\" IS ? AND \"position_revision\" IS ? AND \"motion_stream_id\" IS ? AND \"motion_sequence\" IS ? AND \"hp\" IS ? AND \"hp_revision\" IS ? AND \"attack_one_at\" IS ? AND \"attack_two_at\" IS ? AND \"attack_three_at\" IS ? AND \"attack_four_at\" IS ? AND \"special_guard_until_ms\" IS ? AND \"last_monster_hit_at\" IS ? AND \"combat_lock_until_ms\" IS ? AND \"root_until_ms\" IS ? AND \"stun_until_ms\" IS ? AND \"last_regen_at\" IS ? AND \"last_movement_at_ms\" IS ?",
