 "WITH drops(drop_row) AS (SELECT value FROM json_each(?))\n     INSERT OR IGNORE INTO world_drops\n       (id, owner_id, monster_id, kind, item_name, rarity, power, amount, role, enchantments,\n        x, y, expires_at, collectible_at)\n     SELECT\n       CAST(json_extract(drop_row, '$[0]') AS TEXT),\n       CAST(json_extract(drop_row, '$[1]') AS TEXT),\n       CAST(json_extract(drop_row, '$[2]') AS TEXT),\n       CAST(json_extract(drop_row, '$[3]') AS TEXT),\n       json_extract(drop_row, '$[4]'),\n       CAST(json_extract(drop_row, '$[5]') AS TEXT),\n       CAST(json_extract(drop_row, '$[6]') AS INTEGER),\n       CAST(json_extract(drop_row, '$[7]') AS INTEGER),\n       json_extract(drop_row, '$[8]'),\n       CAST(json_extract(drop_row, '$[9]') AS TEXT),\n       CAST(json_extract(drop_row, '$[10]') AS REAL),\n       CAST(json_extract(drop_row, '$[11]') AS REAL),\n       CAST(json_extract(drop_row, '$[12]') AS INTEGER),\n       CAST(json_extract(drop_row, '$[13]') AS INTEGER)\n     FROM drops\n     WHERE EXISTS (SELECT 1 FROM normal_reward_claims claim\n       WHERE claim.monster_id = ? AND claim.spawn_round = ?\n         AND claim.player_id = CAST(json_extract(drop_row, '$[1]') AS TEXT) AND claim.claim_token = ?)",
 "UPDATE market_shops SET active=0 WHERE active=1 AND created_at<=? AND (created_at<=? OR (NOT EXISTS(SELECT 1 FROM market_listings WHERE shop_id=market_shops.id) AND NOT EXISTS(SELECT 1 FROM premium_listings WHERE seller_id=market_shops.owner_id AND (product NOT IN ('weapon_skin','teleport_skin') OR json_extract(payload,'$.expires_at_ms')>CAST((julianday('now')-2440587.5)*86400000 AS INTEGER)) AND (product!='costume' OR json_extract(payload,'$.item.expires_at_ms')>CAST((julianday('now')-2440587.5)*86400000 AS INTEGER)))))",
 "INSERT OR IGNORE INTO guild_monster_claims(world_cycle,monster_id,spawn_round,guild_id)\n SELECT (SELECT cycle FROM world_state WHERE id=1),monster.id,monster.spawn_round,member.guild_id FROM monsters monster JOIN guild_members member ON member.player_id=?\n WHERE monster.id=? AND monster.spawn_round=? AND monster.hp>0 AND monster.hp<=? AND monster.is_stone=0",
 "WITH batch AS MATERIALIZED (SELECT json_extract(value,'$[0]') AS \"monster_id\",json_extract(value,'$[1]') AS \"spawn_round\",json_extract(value,'$[2]') AS \"player_id\",json_extract(value,'$[3]') AS \"created_at\",json_extract(value,'$[4]') AS \"stone_damage476\",json_extract(value,'$[5]') AS \"stone_first_hit_at_ms476\" FROM json_each(?)) UPDATE main.\"monster_participants\" AS saved SET \"created_at\"=batch.\"created_at\",\"stone_damage476\"=batch.\"stone_damage476\",\"stone_first_hit_at_ms476\"=batch.\"stone_first_hit_at_ms476\" FROM batch WHERE saved.\"monster_id\" IS batch.\"monster_id\" AND saved.\"spawn_round\" IS batch.\"spawn_round\" AND saved.\"player_id\" IS batch.\"player_id\"",
 "UPDATE monsters SET hp = 0, respawn_at = 0\n       WHERE (id = ? OR id LIKE ?)\n         AND (COALESCE((SELECT frozen_zone_enabled FROM combat_settings WHERE id = 1), 1) = 0\n           OR (id = ? AND COALESCE((SELECT frozen_boss_enabled FROM combat_settings WHERE id = 1), 1) = 0)\n           OR (id LIKE ? AND COALESCE((SELECT frozen_water_enabled FROM combat_settings WHERE id = 1), 1) = 0)) AND monsters.channel=? AND monsters.id IN (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
 "INSERT INTO kernel511_channel_receipts VALUES(?,?,?,?,?,?,?)",
 "UPDATE monsters SET hp = 0, respawn_at = ? + CASE WHEN area = 'forest' THEN COALESCE((SELECT forest_monster_respawn_seconds FROM combat_settings WHERE id=1),18) WHEN area = 'frozen' THEN COALESCE((SELECT frozen_monster_respawn_seconds FROM combat_settings WHERE id=1),18) WHEN area = 'ancient' THEN COALESCE((SELECT ancient_monster_respawn_seconds FROM combat_settings WHERE id=1),25) WHEN area = 'black' THEN COALESCE((SELECT black_monster_respawn_seconds FROM combat_settings WHERE id=1),18) WHEN area = 'afk' THEN COALESCE((SELECT afk_island_respawn_seconds FROM combat_settings WHERE id=1),12) ELSE 18 END\n       WHERE area!='event' AND summoned = 0 AND hp <= 0 AND respawn_at <= 0 AND is_boss = 0 AND is_stone = 0\n         AND id != ? AND id != ? AND id NOT LIKE ? AND id != 'dragon-world-1' AND id NOT IN ('stone-boss-black-c1','stone-boss-black-c2','stone-boss-black-c3')",
 "UPDATE monsters SET hp = 0, respawn_at = ? + CASE WHEN area = 'forest' THEN COALESCE((SELECT forest_monster_respawn_seconds FROM combat_settings WHERE id=1),18) WHEN area = 'frozen' THEN COALESCE((SELECT frozen_monster_respawn_seconds FROM combat_settings WHERE id=1),18) WHEN area = 'ancient' THEN COALESCE((SELECT ancient_monster_respawn_seconds FROM combat_settings WHERE id=1),25) WHEN area = 'black' THEN COALESCE((SELECT black_monster_respawn_seconds FROM combat_settings WHERE id=1),18) WHEN area = 'afk' THEN COALESCE((SELECT afk_island_respawn_seconds FROM combat_settings WHERE id=1),12) ELSE 18 END\n       WHERE area!='event' AND summoned = 0 AND hp <= 0 AND respawn_at <= 0 AND is_boss = 0 AND is_stone = 0\n         AND id != ? AND id != ? AND id NOT LIKE ? AND id != 'dragon-world-1' AND id NOT IN ('stone-boss-black-c1','stone-boss-black-c2','stone-boss-black-c3','stone-boss-black-c4') AND monsters.channel=? AND monsters.id IN (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
 "UPDATE pve_engagements SET attackers489=json_set(attackers489,?,json(?)),hit_sequence=hit_sequence+1,updated_at_ms=?,expires_at_ms=MAX(expires_at_ms,?),last_skill_at_ms=? WHERE player_id=? AND json_extract(attackers489,?)=? AND changes()>0",
 "UPDATE market_shops SET active = 0\n       WHERE active = 1 AND created_at <= ?\n         AND (created_at <= ? OR (NOT EXISTS (SELECT 1 FROM market_listings WHERE shop_id = market_shops.id) AND NOT EXISTS(SELECT 1 FROM premium_listings WHERE seller_id=market_shops.owner_id AND (product NOT IN ('weapon_skin','teleport_skin') OR json_extract(payload,'$.expires_at_ms')>CAST((julianday('now')-2440587.5)*86400000 AS INTEGER)) AND (product!='costume' OR json_extract(payload,'$.item.expires_at_ms')>CAST((julianday('now')-2440587.5)*86400000 AS INTEGER)))))",
